/**
 * Canvas of `public/brand/color/email/wordmark.png`, used by email headers
 * because email clients strip inline SVG. Six times {@link EMAIL_WORDMARK_SIZE},
 * so the mark stays crisp on high-density screens.
 *
 * A sent email keeps the `width`/`height` it was sent with and refetches this
 * URL forever, so once Nexora has sent mail, re-export a new logo onto this same
 * canvas (generated by `scripts/brand/generate_assets.py`).
 */
export const EMAIL_WORDMARK_CANVAS = { width: 600, height: 102 } as const

/**
 * Display box for the email header wordmark: the x-height-only "nexora" mark
 * at about 15px of ink, next to 16px body copy. Both dimensions are pinned
 * because email clients do no responsive image selection.
 */
export const EMAIL_WORDMARK_SIZE = { width: 100, height: 17 } as const
